'use client';

import { ark, type HTMLArkProps } from '@ark-ui/react/factory';
import {
  Menu as MenuPrimitive,
  useMenu,
  useMenuContext,
  useMenuItemContext,
} from '@ark-ui/react/menu';
import { clsx } from 'clsx';
import type { ComponentProps, ComponentRef } from 'react';
import { forwardRef } from 'react';
import { CheckIcon, ChevronDownIcon, ChevronRightIcon } from '@/lib/moduix/icons/ui';
import {
  OverlayPortal,
  OverlayPortalProvider,
  type OverlayPortalProps,
} from '@/lib/moduix/overlayPortal';
import styles from './Menu.module.css';

type MenuIndicatorPosition = 'start' | 'end' | 'none';
type MenuItemTone = 'default' | 'destructive';
type MenuItemProps = ComponentProps<typeof MenuPrimitive.Item> & {
  tone?: MenuItemTone;
};
type MenuCheckboxItemProps = ComponentProps<typeof MenuPrimitive.CheckboxItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRadioItemProps = ComponentProps<typeof MenuPrimitive.RadioItem> & {
  indicator?: MenuIndicatorPosition;
};
type MenuRootProps = ComponentProps<typeof MenuPrimitive.Root> & OverlayPortalProps;
type MenuRootProviderProps = ComponentProps<typeof MenuPrimitive.RootProvider> & OverlayPortalProps;

function Menu({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: MenuRootProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <MenuPrimitive.Root lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props} />
    </OverlayPortalProvider>
  );
}

function MenuRootProvider({
  lazyMount = true,
  portalled,
  portalRef,
  unmountOnExit = true,
  ...props
}: MenuRootProviderProps) {
  return (
    <OverlayPortalProvider portalled={portalled} portalRef={portalRef}>
      <MenuPrimitive.RootProvider lazyMount={lazyMount} unmountOnExit={unmountOnExit} {...props} />
    </OverlayPortalProvider>
  );
}

const MenuTrigger = forwardRef<
  ComponentRef<typeof MenuPrimitive.Trigger>,
  ComponentProps<typeof MenuPrimitive.Trigger>
>(function MenuTrigger(props, ref) {
  return <MenuPrimitive.Trigger ref={ref} {...props} data-slot="menu-trigger" />;
});

const MenuIndicator = forwardRef<
  ComponentRef<typeof MenuPrimitive.Indicator>,
  ComponentProps<typeof MenuPrimitive.Indicator>
>(function MenuIndicator({ className, children, ...props }, ref) {
  return (
    <MenuPrimitive.Indicator
      ref={ref}
      className={clsx(styles.indicator, className)}
      {...props}
      data-slot="menu-indicator"
    >
      {children ?? <ChevronDownIcon />}
    </MenuPrimitive.Indicator>
  );
});

const MenuContextTrigger = forwardRef<
  ComponentRef<typeof MenuPrimitive.ContextTrigger>,
  ComponentProps<typeof MenuPrimitive.ContextTrigger>
>(function MenuContextTrigger(props, ref) {
  return <MenuPrimitive.ContextTrigger ref={ref} {...props} data-slot="menu-context-trigger" />;
});

const MenuPositioner = forwardRef<
  ComponentRef<typeof MenuPrimitive.Positioner>,
  ComponentProps<typeof MenuPrimitive.Positioner>
>(function MenuPositioner({ className, ...props }, ref) {
  return (
    <OverlayPortal>
      <MenuPrimitive.Positioner
        ref={ref}
        className={clsx(styles.positioner, className)}
        {...props}
        data-slot="menu-positioner"
      />
    </OverlayPortal>
  );
});

const MenuContent = forwardRef<
  ComponentRef<typeof MenuPrimitive.Content>,
  ComponentProps<typeof MenuPrimitive.Content>
>(function MenuContent({ className, ...props }, ref) {
  return (
    <MenuPrimitive.Content
      ref={ref}
      className={clsx(styles.content, className)}
      {...props}
      data-slot="menu-content"
    />
  );
});

const MenuViewport = forwardRef<ComponentRef<typeof ark.div>, HTMLArkProps<'div'>>(
  function MenuViewport({ className, ...props }, ref) {
    return (
      <ark.div
        ref={ref}
        className={clsx(styles.viewport, className)}
        {...props}
        data-scope="menu"
        data-part="viewport"
        data-slot="menu-viewport"
      />
    );
  },
);

const MenuArrow = forwardRef<
  ComponentRef<typeof MenuPrimitive.Arrow>,
  ComponentProps<typeof MenuPrimitive.Arrow>
>(function MenuArrow({ children, ...props }, ref) {
  return (
    <MenuPrimitive.Arrow ref={ref} {...props} data-slot="menu-arrow">
      {children ?? <MenuArrowTip />}
    </MenuPrimitive.Arrow>
  );
});

const MenuArrowTip = forwardRef<
  ComponentRef<typeof MenuPrimitive.ArrowTip>,
  ComponentProps<typeof MenuPrimitive.ArrowTip>
>(function MenuArrowTip({ className, ...props }, ref) {
  return (
    <MenuPrimitive.ArrowTip
      ref={ref}
      className={clsx(styles.arrowTip, className)}
      {...props}
      data-slot="menu-arrow-tip"
    />
  );
});

const MenuItem = forwardRef<ComponentRef<typeof MenuPrimitive.Item>, MenuItemProps>(
  function MenuItem({ className, tone = 'default', ...props }, ref) {
    return (
      <MenuPrimitive.Item
        ref={ref}
        className={clsx(styles.item, className)}
        {...props}
        data-tone={tone}
        data-slot="menu-item"
      />
    );
  },
);

const MenuTriggerItem = forwardRef<
  ComponentRef<typeof MenuPrimitive.TriggerItem>,
  ComponentProps<typeof MenuPrimitive.TriggerItem>
>(function MenuTriggerItem({ className, ...props }, ref) {
  return (
    <MenuPrimitive.TriggerItem
      ref={ref}
      className={clsx(styles.triggerItem, className)}
      {...props}
      data-slot="menu-trigger-item"
    />
  );
});

const MenuTriggerItemIcon = forwardRef<HTMLSpanElement, ComponentProps<'span'>>(
  function MenuTriggerItemIcon({ className, children, ...props }, ref) {
    return (
      <span
        ref={ref}
        className={clsx(styles.triggerItemIcon, className)}
        {...props}
        data-slot="menu-trigger-item-icon"
      >
        {children ?? <ChevronRightIcon />}
      </span>
    );
  },
);

const MenuSeparator = forwardRef<
  ComponentRef<typeof MenuPrimitive.Separator>,
  ComponentProps<typeof MenuPrimitive.Separator>
>(function MenuSeparator({ className, ...props }, ref) {
  return (
    <MenuPrimitive.Separator
      ref={ref}
      className={clsx(styles.separator, className)}
      {...props}
      data-slot="menu-separator"
    />
  );
});

const MenuItemGroup = forwardRef<
  ComponentRef<typeof MenuPrimitive.ItemGroup>,
  ComponentProps<typeof MenuPrimitive.ItemGroup>
>(function MenuItemGroup({ className, ...props }, ref) {
  return (
    <MenuPrimitive.ItemGroup
      ref={ref}
      className={clsx(styles.itemGroup, className)}
      {...props}
      data-slot="menu-item-group"
    />
  );
});

const MenuItemGroupLabel = forwardRef<
  ComponentRef<typeof MenuPrimitive.ItemGroupLabel>,
  ComponentProps<typeof MenuPrimitive.ItemGroupLabel>
>(function MenuItemGroupLabel({ className, ...props }, ref) {
  return (
    <MenuPrimitive.ItemGroupLabel
      ref={ref}
      className={clsx(styles.itemGroupLabel, className)}
      {...props}
      data-slot="menu-item-group-label"
    />
  );
});

const MenuRadioItemGroup = forwardRef<
  ComponentRef<typeof MenuPrimitive.RadioItemGroup>,
  ComponentProps<typeof MenuPrimitive.RadioItemGroup>
>(function MenuRadioItemGroup({ className, ...props }, ref) {
  return (
    <MenuPrimitive.RadioItemGroup
      ref={ref}
      className={clsx(styles.radioItemGroup, className)}
      {...props}
      data-slot="menu-radio-item-group"
    />
  );
});

const MenuRadioItem = forwardRef<ComponentRef<typeof MenuPrimitive.RadioItem>, MenuRadioItemProps>(
  function MenuRadioItem({ className, indicator = 'start', ...props }, ref) {
    return (
      <MenuPrimitive.RadioItem
        ref={ref}
        className={clsx(styles.radioItem, className)}
        {...props}
        data-indicator-position={indicator}
        data-slot="menu-radio-item"
      />
    );
  },
);

const MenuCheckboxItem = forwardRef<
  ComponentRef<typeof MenuPrimitive.CheckboxItem>,
  MenuCheckboxItemProps
>(function MenuCheckboxItem({ className, indicator = 'start', ...props }, ref) {
  return (
    <MenuPrimitive.CheckboxItem
      ref={ref}
      className={clsx(styles.checkboxItem, className)}
      {...props}
      data-indicator-position={indicator}
      data-slot="menu-checkbox-item"
    />
  );
});

const MenuItemIndicator = forwardRef<
  ComponentRef<typeof MenuPrimitive.ItemIndicator>,
  ComponentProps<typeof MenuPrimitive.ItemIndicator>
>(function MenuItemIndicator({ className, children, ...props }, ref) {
  return (
    <MenuPrimitive.ItemIndicator
      ref={ref}
      className={clsx(styles.itemIndicator, className)}
      {...props}
      data-slot="menu-item-indicator"
    >
      {children ?? <CheckIcon />}
    </MenuPrimitive.ItemIndicator>
  );
});

const MenuItemText = forwardRef<
  ComponentRef<typeof MenuPrimitive.ItemText>,
  ComponentProps<typeof MenuPrimitive.ItemText>
>(function MenuItemText({ className, ...props }, ref) {
  return (
    <MenuPrimitive.ItemText
      ref={ref}
      className={clsx(styles.itemText, className)}
      {...props}
      data-slot="menu-item-text"
    />
  );
});

const MenuItemTextContent = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function MenuItemTextContent({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextContent, className)}
        {...props}
        data-slot="menu-item-text-content"
      />
    );
  },
);

const MenuItemTextIcon = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function MenuItemTextIcon({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextIcon, className)}
        {...props}
        data-slot="menu-item-text-icon"
      />
    );
  },
);

const MenuItemTextLabel = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function MenuItemTextLabel({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemTextLabel, className)}
        {...props}
        data-slot="menu-item-text-label"
      />
    );
  },
);

const MenuItemShortcut = forwardRef<ComponentRef<typeof ark.span>, HTMLArkProps<'span'>>(
  function MenuItemShortcut({ className, ...props }, ref) {
    return (
      <ark.span
        ref={ref}
        className={clsx(styles.itemShortcut, className)}
        {...props}
        data-slot="menu-item-shortcut"
      />
    );
  },
);

const MenuContext = MenuPrimitive.Context;
const MenuItemContext = MenuPrimitive.ItemContext;

export {
  Menu,
  MenuArrow,
  MenuArrowTip,
  MenuCheckboxItem,
  MenuContext,
  MenuContextTrigger,
  MenuContent,
  MenuIndicator,
  MenuItem,
  MenuItemContext,
  MenuItemGroup,
  MenuItemGroupLabel,
  MenuItemIndicator,
  MenuItemShortcut,
  MenuItemText,
  MenuItemTextContent,
  MenuItemTextIcon,
  MenuItemTextLabel,
  MenuPositioner,
  MenuRadioItem,
  MenuRadioItemGroup,
  MenuRootProvider,
  MenuSeparator,
  MenuTrigger,
  MenuTriggerItem,
  MenuTriggerItemIcon,
  MenuViewport,
  useMenu,
  useMenuContext,
  useMenuItemContext,
};

export type {
  MenuArrowProps,
  MenuArrowTipProps,
  MenuContentProps,
  MenuContextProps,
  MenuContextTriggerProps,
  MenuFocusOutsideEvent,
  MenuHighlightChangeDetails,
  MenuIndicatorProps,
  MenuInteractOutsideEvent,
  MenuItemContextProps,
  MenuItemGroupLabelProps,
  MenuItemGroupProps,
  MenuItemIndicatorProps,
  MenuItemTextProps,
  MenuOpenChangeDetails,
  MenuPointerDownOutsideEvent,
  MenuPositionerProps,
  MenuRadioItemGroupProps,
  MenuSelectionDetails,
  MenuSeparatorProps,
  MenuTriggerItemProps,
  MenuTriggerProps,
  MenuTriggerValueChangeDetails,
  MenuValueChangeDetails,
  UseMenuContext,
  UseMenuItemContext,
  UseMenuProps,
  UseMenuReturn,
} from '@ark-ui/react/menu';

export type {
  MenuCheckboxItemProps,
  MenuIndicatorPosition,
  MenuItemProps,
  MenuItemTone,
  MenuRadioItemProps,
  MenuRootProps,
  MenuRootProviderProps,
};

@layer moduix.components {
  .indicator,
  .triggerItemIcon,
  .itemIndicator {
    display: inline-flex;
    flex-shrink: 0;
    align-items: center;
    justify-content: center;

    & > svg {
      width: 100%;
      height: 100%;
    }
  }

  .indicator {
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
  }

  .positioner {
    z-index: var(--z-index);
  }

  .content {
    --arrow-size: var(--moduix-spacing-2-5);
    --arrow-background: var(--moduix-color-popover);

    position: relative;
    z-index: calc(var(--moduix-z-popup) + var(--layer-index, 0));
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    min-width: min(
      max(var(--reference-width, 0px), var(--moduix-menu-popup-min-width, 12rem)),
      var(--available-width, 100vw)
    );
    max-width: min(var(--moduix-menu-popup-max-width, 20rem), var(--available-width, 100vw));
    padding-block: var(--moduix-popup-list-padding-y, var(--moduix-spacing-1));
    border-radius: var(--moduix-radius-md);
    background-color: var(--moduix-color-popover);
    color: var(--moduix-color-popover-foreground);
    /* An outline instead of a border lets MenuArrow paint over the edge and join it. */
    outline: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    box-shadow: var(--moduix-shadow-lg);
    transform-origin: var(--transform-origin);

    &[data-state='open'] {
      animation: global(moduix-popup-in)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out));
    }

    &[data-state='closed'] {
      animation: global(moduix-popup-out)
        var(--moduix-popup-motion-duration, var(--moduix-duration-normal))
        var(--moduix-popup-motion-easing, var(--moduix-ease-in-out)) forwards;
    }
  }

  .viewport {
    display: flex;
    max-height: min(var(--moduix-menu-popup-max-height, 24rem), var(--available-height, 100dvh));
    flex-direction: column;
    overflow: auto;
  }

  .arrowTip {
    border-block-start: var(--moduix-border-width-sm) solid var(--moduix-color-border);
    border-inline-start: var(--moduix-border-width-sm) solid var(--moduix-color-border);
  }

  .item,
  .triggerItem,
  .radioItem,
  .checkboxItem {
    position: relative;
    box-sizing: border-box;
    min-height: var(--moduix-popup-item-min-height, var(--moduix-size-sm));
    margin: 0;
    border: 0;
    border-radius: var(--moduix-radius-sm);
    padding-block: var(--moduix-popup-item-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3))
      var(--moduix-popup-item-padding-x-end, var(--moduix-spacing-3));
    outline: 0;
    color: inherit;
    font: inherit;
    font-size: var(--moduix-popup-item-font-size, var(--moduix-text-sm));
    line-height: var(--moduix-popup-item-line-height, var(--moduix-line-height-text-sm));
    text-decoration: none;
    user-select: none;
    cursor: default;

    /* The highlight is inset from the row, so the whole row stays clickable. */
    &:is([data-highlighted], [data-state='open']) {
      z-index: 0;
      color: var(--moduix-color-accent-foreground);

      &::before {
        content: '';
        position: absolute;
        z-index: -1;
        inset-block: 0;
        inset-inline: var(--moduix-popup-highlight-inset-x, var(--moduix-spacing-1));
        border-radius: var(--moduix-popup-highlight-radius, var(--moduix-radius-sm));
        background-color: var(--moduix-color-accent);
      }
    }

    &[data-tone='destructive'] {
      color: var(--moduix-color-destructive);

      &[data-highlighted]::before {
        background-color: color-mix(in oklab, var(--moduix-color-destructive) 12%, transparent);
      }
    }

    /* After the tone, so a disabled destructive item is muted too. */
    &[data-disabled] {
      pointer-events: none;
      color: var(--moduix-color-muted-foreground);
    }
  }

  .item {
    display: flex;
    align-items: center;
    gap: var(--moduix-spacing-2);
  }

  .triggerItem {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--moduix-spacing-3);
  }

  .triggerItemIcon {
    width: var(--moduix-spacing-3-5);
    height: var(--moduix-spacing-3-5);

    &:dir(rtl) {
      transform: scaleX(-1);
    }
  }

  .itemGroup,
  .radioItemGroup {
    display: grid;
  }

  .itemGroupLabel {
    margin: 0;
    padding-block: var(--moduix-popup-group-label-padding-y, var(--moduix-spacing-1));
    padding-inline: var(--moduix-popup-group-label-padding-x-start, var(--moduix-spacing-2-5))
      var(--moduix-popup-group-label-padding-x-end, var(--moduix-spacing-3));
    color: var(--moduix-popup-group-label-color, var(--moduix-color-muted-foreground));
    font-size: var(--moduix-popup-group-label-font-size, var(--moduix-text-xs));
    font-weight: var(--moduix-popup-group-label-font-weight, var(--moduix-weight-regular));
    line-height: var(--moduix-popup-group-label-line-height, var(--moduix-line-height-text-xs));
    user-select: none;
    cursor: default;
  }

  .radioItem,
  .checkboxItem {
    --_menu-indicator-size: var(--moduix-popup-check-indicator-size, var(--moduix-spacing-3));

    display: grid;
    grid-template-columns: var(--_menu-indicator-size) minmax(0, 1fr);
    align-items: center;
    gap: var(--moduix-popup-check-gap, var(--moduix-spacing-2));
    padding-inline-start: var(--moduix-popup-check-padding-x-start, var(--moduix-spacing-2-5));

    &[data-indicator-position='none'] {
      grid-template-columns: minmax(0, 1fr);
      padding-inline-start: var(--moduix-popup-item-padding-x-start, var(--moduix-spacing-3));

      & > .itemIndicator {
        display: none;
      }

      & > .itemText {
        grid-column-start: 1;
      }
    }

    &[data-indicator-position='end'] {
      grid-template-columns: minmax(0, 1fr) var(--_menu-indicator-size);

      & > .itemText {
        grid-column-start: 1;
      }

      & > .itemIndicator {
        grid-column-start: 2;
        justify-self: end;
      }
    }
  }

  .itemIndicator {
    grid-column-start: 1;
    width: var(--_menu-indicator-size, var(--moduix-spacing-3));
    height: var(--_menu-indicator-size, var(--moduix-spacing-3));
  }

  .itemText {
    grid-column-start: 2;
    min-width: 0;
    overflow: hidden;
  }

  .itemTextContent {
    display: inline-flex;
    max-width: 100%;
    min-width: 0;
    align-items: center;
    gap: var(--moduix-spacing-2);
    vertical-align: top;
  }

  .itemTextIcon {
    display: inline-flex;
    width: var(--moduix-spacing-4);
    height: var(--moduix-spacing-4);
    flex-shrink: 0;
    align-items: center;
    justify-content: center;
  }

  .itemTextLabel {
    min-width: 0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .itemShortcut {
    margin-inline-start: auto;
    padding-inline-start: var(--moduix-spacing-4);
    color: var(--moduix-color-muted-foreground);
    font-size: var(--moduix-text-xs);
    line-height: var(--moduix-line-height-text-xs);
    white-space: nowrap;
  }

  .separator {
    box-sizing: border-box;
    height: var(--moduix-border-width-sm);
    margin-block: var(--moduix-popup-separator-margin-y, var(--moduix-spacing-1-5));
    margin-inline: var(--moduix-popup-separator-margin-x-start, var(--moduix-spacing-3))
      var(--moduix-popup-separator-margin-x-end, var(--moduix-spacing-3));
    border: 0;
    background-color: var(--moduix-color-border);
  }

  @media (prefers-reduced-motion: reduce) {
    .content[data-state] {
      animation-delay: 0ms;
      animation-duration: 1ms;
    }
  }
}
